const puppeteer=require('puppeteer-core');const base='http://127.0.0.1:8000/';const vps=[[1920,1080],[1440,900],[768,1024],[390,844],[360,800]];const failures=[];const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const b=await puppeteer.launch({executablePath:process.env.CHROME,headless:true,args:['--no-sandbox']});try{for(const route of ['privacy.html','legal.html'])for(const [w,h] of vps){const p=await b.newPage();await p.setViewport({width:w,height:h});await p.goto(base+route,{waitUntil:'domcontentloaded',timeout:30000});await sleep(250);const m=await p.evaluate(()=>{const R=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{x:r.x,right:r.right,width:r.width,height:r.height,bottom:r.bottom}};const ps=[...document.querySelectorAll('main p')].map(p=>({text:p.textContent.trim().slice(0,100),size:parseFloat(getComputedStyle(p).fontSize),cls:p.className||'',width:p.getBoundingClientRect().width}));const actions=[...document.querySelectorAll('main .button-link,main .legal-link-row a')].map(a=>({text:a.textContent.trim(),...R(a)}));const caps=[...document.querySelectorAll('main .section-cap')].map(R);return{sw:document.documentElement.scrollWidth,ps,actions,caps,heroBefore:getComputedStyle(document.querySelector('.legal-hero'),'::before').backgroundImage,company:R([...document.querySelectorAll('main strong')].find(e=>e.textContent.includes('UNIQE OTOMOTİV'))),address:R(document.querySelector('main address')),emails:[...document.querySelectorAll('main a[href^="mailto:"]')].map(a=>({text:a.textContent.trim(),...R(a)}))}});for(const x of m.ps)if(x.text&&x.size<15)failures.push({route,w,h,type:'paragraph-font',x});for(const x of m.caps)if(x.width>Math.min(w,1000)+2)failures.push({route,w,h,type:'line-length',x});for(const x of m.emails)if(x.x<-1||x.right>w+1)failures.push({route,w,h,type:'email-clip',x});if(m.company&&(m.company.x<-1||m.company.right>w+1))failures.push({route,w,h,type:'company-clip',x:m.company});if(m.address&&(m.address.x<-1||m.address.right>w+1))failures.push({route,w,h,type:'address-clip',x:m.address});if(w<=390)for(const x of m.actions)if(x.x<-1||x.right>w+1||x.height<40)failures.push({route,w,h,type:'mobile-action',x});if(/url\(/i.test(m.heroBefore))failures.push({route,w,h,type:'hero-url',heroBefore:m.heroBefore});await p.close()}}finally{await b.close()}console.log(JSON.stringify({count:failures.length,failures},null,2));process.exit(failures.length?1:0)})();